import { HttpClient } from '@angular/common/http';
import { Component } from '@angular/core';

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.css']
})
export class RegisterComponent {
  form = { ime: '', username: '', email: '', password: '', repeatPassword: '', ulogaIds: []};

  constructor(private http: HttpClient) { }

  register() {
    if (this.form.password !== this.form.repeatPassword) {
      alert('Passwords do not match!')
      return;
    }
  }
  onSubmit() {
    this.http.post('https://localhost:44413//api/auth/register', this.form).subscribe({
      next: res => alert('Registration successful'),
      error: err => alert('err.error.message' || 'Registration failed')
    });
  }
}
<h2>Register</h2>
<form (ngSubmit)="onSubmit()" #registerForm="ngForm">
  <input name="ime" [(ngModel)]="form.ime" placeholder="Name" required />
  <input name="isername" [(ngModel)]="form.username" placeholder="Username" required />
  <input name="email" [(ngModel)]="form.email" placeholder="Email" required />
  <input type="password" name="password" [(ngModel)]="form.password" placeholder="Password" required />
  <input type="password" name="repeatPassword" [(ngModel)]="form.repeatPassword" placeholder="Repeat password" required />

  <button type="submit">Register</button>
</form>
